const DEFAULT_OFFERS_DISCLOSURE = "Affiliate disclosure: Prop Firm Lenz may receive compensation from prop firms when you click an offer link or purchase an evaluation. This does not influence our independent ratings, payout tracking, or verified reviews.";
const DEFAULT_VERIFICATION_EXPLAINER = "Every discount code and promotional deal listed on Prop Firm Lenz undergoes testing directly at the firm’s checkout page before publication. Our team verifies code validity, percentage deduction, eligible challenge sizes, and expiry terms. If a code fails or expires, it is promptly updated or flagged for re-check. Firms cannot buy higher percentage ratings or manipulate order placement.";

function getOffersAffiliateDisclosure() {
  try {
    return localStorage.getItem('pfl_offers_affiliate_disclosure') || window.PFL_OFFERS_DISCLOSURE || DEFAULT_OFFERS_DISCLOSURE;
  } catch(_) {
    return DEFAULT_OFFERS_DISCLOSURE;
  }
}

