let offersFilter = 'exclusive', offersQuery = '', offersSort = 'discount', offersPlatform = 'all', offersMinDiscount = 'all', offersFreeAccountOnly = false;
const expandedOfferGroups = new Set();

function displayDiscount(x) {
  if (x.discount == null || x.discount === '' || x.discount === '—' || x.discount === '-') return 'Not disclosed';
  return x.discount === 'Offer' ? 'PROMO' : `${safe(x.discount)} <span>OFF</span>`;
}

function getOfferConditions(x) {
  const desc = (x.description || '').toLowerCase();
  if (desc.includes('crypto')) return 'Applies to standard and crypto evaluation challenges';
  if (desc.includes('allocation upgrade') || desc.includes('live traders')) return 'Applies to live trader evaluation and allocation upgrades';
  if (desc.includes('lightning') || desc.includes('sprint')) return 'Applies to sprint, lightning, and standard evaluation challenges';
  if (desc.includes('free same-sized account')) return 'Includes free same-sized account reward upon qualifying funding';
  if (desc.includes('profit reward')) return 'Includes 15% evaluation stage profit reward upon passing';
  return 'Applies to 1-step and 2-step evaluation challenges';
}

function formatOfferTiming(x) {
  const now = new Date();
  if (x.expiryDate) {
    const exp = new Date(x.expiryDate);
    if (!isNaN(exp.getTime())) {
      const diffMs = exp.getTime() - now.getTime();
      const diffDays = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
      const expDateStr = exp.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      if (diffDays >= 0 && diffDays <= 7) {
        return `<span class="offer-timing ending-soon" title="Ends ${expDateStr}"><span class="amber-indicator" aria-hidden="true">●</span> Ending soon</span>`;
      }
      return `<span class="offer-timing">Ends ${expDateStr}</span>`;
    }
  }

  let lastChecked = x.lastChecked ? new Date(x.lastChecked) : null;
  if (!lastChecked) {
    lastChecked = new Date('2026-10-16');
  }
  const diffDaysChecked = Math.floor((now.getTime() - lastChecked.getTime()) / (1000 * 60 * 60 * 24));
  const checkedDateStr = lastChecked.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  if (diffDaysChecked > 14) {
    return `<span class="offer-timing needs-recheck" title="Last checked ${checkedDateStr}">Needs re-check</span>`;
  }
  return `<span class="offer-timing">Last checked ${checkedDateStr}</span>`;
}

function offerRow(x, moreCount = 0) {
  const t = trustpilotFor(x.name);
  const rating = t?.trustpilotRating == null 
    ? '<span class="rating-not-disclosed">Rating: Not disclosed</span>' 
    : `${t.trustpilotRating.toFixed(1)} <span class="rating-out-of">/ 5</span>${t.trustpilotReviews != null ? ` · ${Number(t.trustpilotReviews).toLocaleString()} reviews` : ' · Reviews: Not disclosed'}`;
  const more = moreCount ? `<button class="more-btn" type="button" data-offer-more data-more-count="${moreCount}" aria-expanded="false">More ${moreCount} <span aria-hidden="true">⌄</span></button>` : '';
  const buyUrl = x.buyLink || CHECKOUT_LINKS[x.name] || '#';
  const promoCode = x.code || 'LENZ';
  const condText = getOfferConditions(x);
  const expiryText = x.expiryDate ? ` · Ends ${safe(x.expiryDate)}` : '';
  const sponsoredBadge = x.sponsored ? '<span class="offer-sponsored-tag">Sponsored</span>' : '';
  const timingHtml = formatOfferTiming(x);
  const descText = x.description && x.description !== '—' && x.description !== '-' ? safe(x.description) : 'Not disclosed';

  return `
    <article class="offer-row" data-offer-name="${safe(x.name.toLowerCase())}">
      <div class="offer-discount">
        <span class="offer-flame" aria-hidden="true">◆</span>
        <b>${displayDiscount(x)}</b>
        ${x.extra ? '<span class="free-account">＋ FREE ACCOUNT</span>' : ''}
        ${sponsoredBadge}
      </div>
      <div class="offer-main">
        <div class="offer-firmline">
          ${logo(x.name)}
          <div>
            <h3>${safe(x.name)}</h3>
            <span class="offer-rating">${rating}</span>
          </div>
        </div>
        <p class="offer-desc">${descText}</p>
        <div class="offer-conditions"><span class="cond-bullet">◇</span> <span class="cond-text">${safe(condText)}${expiryText}</span></div>
      </div>
      <div class="offer-actions">
        <span class="offer-code">
          <span class="code-label">Code</span>
          <button class="copy-code-chip" type="button" data-copy-code="${safe(promoCode)}" aria-label="Copy promo code ${safe(promoCode)}">
            <span class="chip-text">${safe(promoCode)}</span> <span class="chip-icon">⧉</span>
          </button>
        </span>
        <a class="buy-link-btn" href="${safe(buyUrl)}" target="_blank" rel="sponsored noopener" aria-label="Buy link for ${safe(x.name)}">Buy link ↗</a>
        ${timingHtml}
        ${more}
      </div>
    </article>
  `;
}

function offerGroup(items) {
  const name = items[0].name, moreCount = items.length - 1, expanded = expandedOfferGroups.has(name);
  return `<section class="offer-group ${expanded ? 'expanded' : ''}" data-offer-group="${safe(name)}">${offerRow(items[0], moreCount)}${moreCount ? `<div class="offer-additional-rows" ${expanded ? '' : 'hidden'}>${items.slice(1).map(x => offerRow(x)).join('')}</div>` : ''}</section>`;
}

