  const countEl=document.querySelector('#compareSelectedCount');
  if(countEl)countEl.textContent=`${count} / 3 selected`;
  const goBtn=document.querySelector('#goCompareBtn');
  if(goBtn)goBtn.textContent=`Compare Firms (${count}/3) →`;
  const chipsEl=document.querySelector('#stickyCompareChips');
