/* ========================================================
   REVIEWS & COMMUNITY RATINGS ENGINE (AUTO-LIVE & 1 PER USER)
   ======================================================== */
let PFL_COMMUNITY_REVIEWS = (function initCommunityReviews() {
  const seed = Array.isArray(PFL_REVIEWS_DATA) ? [...PFL_REVIEWS_DATA] : [];
  try {
    const local = localStorage.getItem('pfl_user_reviews');
    if (local) {
      const parsed = JSON.parse(local);
      if (Array.isArray(parsed)) {
        const seedIds = new Set(seed.map(r => r.id));
        parsed.forEach(r => {
          if (!seedIds.has(r.id)) seed.unshift(r);
        });
      }
    }
  } catch (_) {}
  return seed;
})();

async function syncLiveReviews() {
  try {
    const res = await fetch('/api/reviews');
    if (res.ok) {
      const data = await res.json();
      if (data && Array.isArray(data.reviews)) {
        const existingIds = new Set(PFL_COMMUNITY_REVIEWS.map(r => r.id));
        let added = false;
        data.reviews.forEach(r => {
          if (!existingIds.has(r.id)) {
            PFL_COMMUNITY_REVIEWS.unshift(r);
            existingIds.add(r.id);
            added = true;
          }
        });
        if (added) {
          try {
            localStorage.setItem('pfl_user_reviews', JSON.stringify(PFL_COMMUNITY_REVIEWS.filter(r => !r.id.startsWith('rev-'))));
          } catch (_) {}
          if (currentPage === 'reviews') renderReviews();
        }
      }
    }
  } catch (_) {}
}

if (typeof window !== 'undefined') {
  setTimeout(syncLiveReviews, 800);
}

function hasUserReviewedFirm(email, firmName) {
  if (!email || !firmName) return false;
  const normEmail = email.trim().toLowerCase();
  const normFirm = firmName.trim().toLowerCase();
  return PFL_COMMUNITY_REVIEWS.some(r =>
    r.email && r.email.trim().toLowerCase() === normEmail &&
    r.firm && r.firm.trim().toLowerCase() === normFirm
  );
}

function getFirmReviewMetrics(firmName) {
  const firmReviews = PFL_COMMUNITY_REVIEWS.filter(r => (r.firm || r.firmName) === firmName);
  const count = firmReviews.length;
  const tp = trustpilotFor(firmName);
  const tpRating = tp?.trustpilotRating ?? null;
  const tpCount = Number(tp?.trustpilotReviews) || 0;

  const baseScore = tpRating !== null ? tpRating : 4.5;
  const communityScore = count ? (firmReviews.reduce((sum, r) => sum + Number(r.rating || 5), 0) / count) : baseScore;
  const blendedScore = Number(communityScore.toFixed(1));

  const dist = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };
  firmReviews.forEach(r => {
    const star = Math.min(5, Math.max(1, Math.round(Number(r.rating || 5))));
    dist[star] = (dist[star] || 0) + 1;
  });

  const payoutSpeed = count ? (firmReviews.reduce((sum, r) => sum + Number(r.categories?.payoutSpeed || r.rating || 5), 0) / count) : 4.9;
  const rulesSpreads = count ? (firmReviews.reduce((sum, r) => sum + Number(r.categories?.rulesSpreads || r.rating || 5), 0) / count) : 4.8;
  const support = count ? (firmReviews.reduce((sum, r) => sum + Number(r.categories?.support || r.rating || 5), 0) / count) : 4.8;

  return {
    count,
    totalVolume: tpCount + count,
    avgScore: blendedScore,
    tpRating,
    tpCount,
    dist,
    payoutSpeed: Number(payoutSpeed.toFixed(1)),
    rulesSpreads: Number(rulesSpreads.toFixed(1)),
    support: Number(support.toFixed(1)),
    reviews: firmReviews
  };
}

let reviewTab = 'leaderboard';
let reviewMarket = 'all';
let reviewScoreFilter = 0;
let reviewSort = 'rating';
let reviewQuery = '';

function renderReviewStars(value) {
  const rounded = Math.round(value);
  return '<span class="rev-stars-gold">' +
    [1, 2, 3, 4, 5].map(i => i <= rounded ? '★' : '☆').join('') +
    '</span>';
}
const reviewStars = renderReviewStars;
const reviewFirmLogo = logo;

function timeAgo(dateStr) {
  if (!dateStr) return 'Recently';
  const diff = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 60) return mins <= 1 ? 'Just now' : mins + 'm ago';
  const hours = Math.floor(mins / 60);
  if (hours < 24) return hours + 'h ago';
  const days = Math.floor(hours / 24);
  if (days < 30) return days + (days === 1 ? ' day ago' : ' days ago');
  return new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

function renderReviewsLeaderboard() {
  const rowsEl = document.querySelector('#reviewsLeaderboardRows');
  if (!rowsEl) return;

  const allFirms = TRUSTPILOT_FIRMS.filter(f => {
    if (reviewMarket !== 'all' && !firmInMarket(f.name, reviewMarket)) return false;
    if (reviewQuery && !f.name.toLowerCase().includes(reviewQuery)) return false;
    const metrics = getFirmReviewMetrics(f.name);
    if (reviewScoreFilter > 0 && metrics.avgScore < reviewScoreFilter) return false;
    return true;
  });

  allFirms.sort((a, b) => {
    const ma = getFirmReviewMetrics(a.name);
    const mb = getFirmReviewMetrics(b.name);
    if (reviewSort === 'name') return a.name.localeCompare(b.name);
    if (reviewSort === 'reviews') return mb.totalVolume - ma.totalVolume;
    if (reviewSort === 'trustpilot') return (mb.tpRating ?? -1) - (ma.tpRating ?? -1);
    return mb.avgScore - ma.avgScore || mb.totalVolume - ma.totalVolume;
  });

  const maxVolume = Math.max(1, ...allFirms.map(f => getFirmReviewMetrics(f.name).totalVolume));
  const countBadge = document.querySelector('#reviewActiveCountBadge');
  if (countBadge) countBadge.textContent = allFirms.length + ' firms ranked';

  if (!allFirms.length) {
    rowsEl.innerHTML = '<div style="padding:48px 20px;text-align:center;color:#94A3B8;font-size:14px;">No prop firms match your search and rating criteria.</div>';
    return;
  }

  rowsEl.innerHTML = allFirms.map((f, index) => {
    const m = getFirmReviewMetrics(f.name);
    const barWidth = Math.max(4, Math.min(100, Math.round((m.totalVolume / maxVolume) * 100)));
    const rankLabel = index < 3 ? '★' : (index + 1);

    return '<article class="rev-firm-card-3d">' +
      '<div class="rev-firm-cell">' +
        '<span class="rev-rank-num" data-rank="' + (index + 1) + '">' + rankLabel + '</span>' +
        '<div class="rev-firm-logo-wrap">' + logo(f.name) + '</div>' +
        '<div class="rev-firm-meta">' +
          '<strong>' + safe(f.name) + '</strong>' +
          '<div class="rev-firm-tags">' +
            '<span class="rev-tag-market">' + safe(f.category || 'Prop Firm') + '</span>' +
            (m.count > 0 ? '<span class="rev-tag-market" style="color:#10B981;background:rgba(16,185,129,0.12);">' + m.count + ' Community</span>' : '') +
          '</div>' +
        '</div>' +
      '</div>' +

      /* Category 1: Trustpilot Verified Rating & Count */
      '<div class="rev-dual-cat-tp">' +
        '<div class="rev-tp-header">' +
          '<span class="tp-badge-tag">★ Trustpilot</span>' +
          '<span class="rev-tp-count">' + (m.totalVolume > 0 ? m.totalVolume.toLocaleString() + ' reviews' : 'Unlisted') + '</span>' +
        '</div>' +
        '<div class="rev-tp-score-row">' +
          '<strong>' + (m.tpRating !== null ? m.tpRating.toFixed(1) : '—') + '</strong>' +
          '<span class="tp-stars">' + (m.tpRating ? '★★★★★' : '') + '</span>' +
          '<span style="font-size:10px;color:#94A3B8;">' + (m.tpRating >= 4.5 ? 'Excellent' : m.tpRating >= 4 ? 'Great' : '') + '</span>' +
        '</div>' +
        '<span class="rev-tp-bar" style="display:block;margin-top:4px;height:3px;background:rgba(255,255,255,0.08);border-radius:2px;overflow:hidden;"><i style="display:block;height:100%;background:#00B67A;width:' + barWidth + '%;"></i></span>' +
      '</div>' +

      /* Category 2: Prop Firm Lenz Community Reviews (Own Collection System) */
      '<div class="rev-dual-cat-pfl">' +
        '<div class="rev-pfl-header">' +
          '<span class="pfl-badge-tag">🟣 Prop Firm Lenz</span>' +
          '<span class="rev-pfl-count">' + (m.count > 0 ? m.count + ' verified reviews' : 'Be first to review') + '</span>' +
        '</div>' +
        '<div class="rev-pfl-score-row">' +
          '<strong>' + (m.count > 0 ? m.avgScore.toFixed(1) : '5.0') + '</strong>' +
          '<span class="pfl-stars">' + renderReviewStars(m.avgScore) + '</span>' +
        '</div>' +
      '</div>' +

      '<div class="rev-actions-cell">' +
        '<button class="btn-read-reviews" type="button" data-open-firm-reviews="' + safe(f.name) + '">Read Reviews (' + m.count + ')</button>' +
        '<button class="btn-quick-write" type="button" data-write-for-firm="' + safe(f.name) + '">✍️ Review</button>' +
      '</div>' +
    '</article>';
  }).join('');
}

function renderReviewsFeed() {
  const feedEl = document.querySelector('#reviewsLiveFeedList');
  if (!feedEl) return;

  let reviews = [...PFL_COMMUNITY_REVIEWS];
  if (reviewQuery) {
    const q = reviewQuery.toLowerCase();
    reviews = reviews.filter(r => (r.firm || '').toLowerCase().includes(q) || (r.title || '').toLowerCase().includes(q) || (r.body || '').toLowerCase().includes(q));
  }
  if (reviewMarket !== 'all') {
    reviews = reviews.filter(r => firmInMarket(r.firm, reviewMarket));
  }
  if (reviewScoreFilter > 0) {
    reviews = reviews.filter(r => Number(r.rating || 5) >= reviewScoreFilter);
  }

  const badge = document.querySelector('#feedCountBadge');
  if (badge) badge.textContent = PFL_COMMUNITY_REVIEWS.length;

  if (!reviews.length) {
    feedEl.innerHTML = '<div style="grid-column:1/-1;padding:48px 20px;text-align:center;color:#94A3B8;font-size:14px;">No reviews match this filter. Be the first to post a review!</div>';
    return;
  }

  feedEl.innerHTML = reviews.map(r => {
    const initials = (r.author || 'VT').split(' ').map(w => w[0]).join('').slice(0, 2).toUpperCase();
    return '<article class="feed-card-3d" data-review-id="' + safe(r.id) + '">' +
      '<div class="feed-card-header">' +
        '<div class="feed-author-wrap">' +
          '<div class="feed-avatar">' + initials + '</div>' +
          '<div class="feed-author-info">' +
            '<strong>' + safe(r.author || 'Verified Trader') + '</strong>' +
            '<span>✓ Verified Funded Trader</span>' +
          '</div>' +
        '</div>' +
        '<span class="feed-firm-pill">' + safe(r.firm) + '</span>' +
      '</div>' +

      '<div class="feed-rating-row">' +
        renderReviewStars(r.rating || 5) +
        '<span class="feed-date">' + timeAgo(r.date) + '</span>' +
      '</div>' +

      '<h4 class="feed-title">' + safe(r.title) + '</h4>' +
      '<p class="feed-body">' + safe(r.body) + '</p>' +

      '<div class="feed-footer">' +
        (r.payoutReceived ? '<span class="feed-payout-badge">✓ Payout Verified</span>' : '<span style="font-size:10.5px;color:#94A3B8;">Evaluation Trader</span>') +
        '<button class="feed-helpful-btn" type="button" data-upvote-review="' + safe(r.id) + '">👍 Helpful (' + (r.upvotes || 0) + ')</button>' +
      '</div>' +
    '</article>';
  }).join('');
}

function renderReviews() {
  const lbView = document.querySelector('#reviewsLeaderboardView');
  const feedView = document.querySelector('#reviewsFeedView');
  if (lbView) lbView.hidden = false;
  if (feedView) feedView.hidden = true;

  const totalReviewsCount = TRUSTPILOT_FIRMS.reduce((sum, f) => sum + (Number(f.trustpilotReviews) || 0), 0) + PFL_COMMUNITY_REVIEWS.length;
  const revTotalEl = document.querySelector('#revTotalCount');
  if (revTotalEl) revTotalEl.textContent = totalReviewsCount.toLocaleString() + '+';

  const revFirmEl = document.querySelector('#revFirmCount');
  if (revFirmEl) revFirmEl.textContent = TRUSTPILOT_FIRMS.length + ' Firms';

  renderReviewsLeaderboard();
}

