function profileBuyButton(f,label='Buy Challenge ↗'){const link=f.buyLink||CHECKOUT_LINKS[f.name]||'';return `<button class="profile-buy" type="button" data-profile-buy data-buy-link="${safe(link)}" ${link?'':'disabled'}>${link?safe(label):'Buy link unavailable'}</button>`}
