  if(f.features&&f.features.length)parts.push(`<div class="profile-subsection"><span class="profile-label">Verified Highlights</span><ul class="profile-feature-list">${f.features.map(x=>`<li>${safe(x)}</li>`).join('')}</ul></div>`);
  if((f.platforms&&f.platforms.length)||(f.assets&&f.assets.length))parts.push(`<div class="profile-subsection profile-overview-grid">${f.platforms&&f.platforms.length?`<div><span class="profile-label">Trading Platforms</span><div class="profile-tags">${f.platforms.map(x=>`<span>${safe(x)}</span>`).join('')}</div></div>`:''}${f.assets&&f.assets.length?`<div><span class="profile-label">Tradable Instruments & Assets</span><div class="profile-tags">${f.assets.map(x=>`<span>${safe(x)}</span>`).join('')}</div></div>`:''}</div>`);
