  const heroTitle=document.querySelector('#heroTitle');
  const heroSubtitle=document.querySelector('#heroSubtitle');
  const heroFirmCount=document.querySelector('#heroFirmCount');
  const heroFirmLabel=document.querySelector('#heroFirmLabel');
  const heroChallengeCount=document.querySelector('#heroChallengeCount');
  const heroChallengeLabel=document.querySelector('#heroChallengeLabel');
  const heroOfferCount=document.querySelector('#heroOfferCount');
  const heroOfferLabel=document.querySelector('#heroOfferLabel');
  const heroPayoutFirmCount=document.querySelector('#heroPayoutFirmCount');
  const heroPayoutLabel=document.querySelector('#heroPayoutLabel');

